import numpy as np
from scipy.optimize import least_squares
fams={
 'exp(-k/e)*T^b': lambda p: np.exp(-p[1]/eps)*T**p[2],
 'exp(-k e)*T^b': lambda p: np.exp(-p[1]*eps)*T**p[2],
 'T^b*e^a + exp': lambda p: eps**p[0]*T**p[2],
}
for n,f in fams.items():
    best=None
    rng=np.random.default_rng(5)
    def model(p):
        A=np.column_stack([1/eps,(eps/(1+p[3]*eps))*T**3,T**p[4],f(p)])
        co=np.linalg.lstsq(A,sigma,rcond=None)[0]
        return sigma-A@co
    for k in range(80):
        p0=[rng.uniform(-2,2),rng.uniform(0.05,3),rng.uniform(-2,3),rng.uniform(0.2,2),rng.uniform(0,3)]
        try:
            r=least_squares(model,p0)
            v=np.mean(r.fun**2)/np.var(sigma)
